if(file.exists(file.path(root,'tables/Cervilla_cell_predictions.tsv.gz')) && Sys.getenv('HD_RECOMPUTE')!='1')quit(save='no')
source(file.path(A,'segmentation_assignment_v2/code/load_result.R'));o<-load_assignment(file.path(A,'segmentation_assignment_v2/Cervilla'),qc='analysis');c<-LayerData(o,assay='RNA',layer='counts');g<-fread(file.path(A,'segmentation_assignment_v2/Cervilla/gene_mapping_conservation.tsv'));print(names(g));flush.console()
# Original gene ID to symbol: aligned by ID, never make.unique across datasets.
hd<-rd('hd_genes.tsv');sy<-hd$symbol[match(rownames(c),hd$gene_id)];stopifnot(!anyNA(sy));lev<-unique(sy);G<-sparseMatrix(i=match(sy,lev),j=seq_along(sy),x=1,dims=c(length(lev),length(sy)));z<-G%*%c;rownames(z)<-lev;q<-lognorm(z);rm(o,c,z);gc()
