d$fine_prediction[valid]<-z$labels;d$fine_pruned[valid]<-ifelse(bad,NA,z$labels);d$delta_next[valid]<-z$delta.next;d$delta_median[valid]<-getDeltaFromMedian(z);put(d,'Cervilla_cell_predictions.tsv.gz');saveRDS(list(ids=rownames(z),scores=z$scores,meaning='correlations not probabilities; pre-fine-tuning'),file.path(root,'models/Cervilla_cell_scores.rds'));cat('CELLS_COMPLETE\n')
